// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.downloadimport okhttp3.OkHttpClientimport okhttp3.Requestimport timber.log.Timberimport java.io.Fileimport java.io.FileOutputStreamimport java.io.RandomAccessFileimport java.security.MessageDigest/** * NOUS — GGUF Model Downloader. * * Downloads .gguf model files with: *   - SHA256 checksum verification (prevents corrupted models) *   - Resume support (HTTP Range header — don't restart from scratch) *   - Progress callback (for UI progress bar) *   - App-Heap-aware quantization recommendation * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§8 Model Downloader</a> */class ModelDownloader(    private val httpClient: OkHttpClient,    /** Directory where models are stored. */    private val modelsDir: String,) {    /**     * Download a model file.     *     * @param url HTTPS URL to .gguf file     * @param expectedSha256 expected SHA256 hash (null to skip verification)     * @param expectedSize expected file size in bytes (for progress)     * @param onProgress callback (0.0 to 1.0)     * @return path to downloaded file, or null on failure     */    suspend fun download(        url: String,        expectedSha256: String?,        expectedSize: Long,        onProgress: (Float) -> Unit,    ): String? {        val fileName = url.substringAfterLast("/")        val targetFile = File(modelsDir, fileName)        return try {            // Check for partial download (resume support)            val existingSize = if (targetFile.exists()) targetFile.length() else 0L            val requestBuilder = Request.Builder().url(url)            if (existingSize > 0) {                requestBuilder.header("Range", "bytes=$existingSize-")                Timber.i("Resuming download: $fileName from byte $existingSize")            }            val response = httpClient.newCall(requestBuilder.build()).execute()            if (!response.isSuccessful) {                Timber.e("Download failed: HTTP ${response.code}")                return null            }            val responseBody = response.body ?: return null            val totalSize = existingSize + responseBody.contentLength()            val digest = MessageDigest.getInstance("SHA-256")            // Open file for append (if resuming) or create new            val outputStream = if (existingSize > 0) {                FileOutputStream(targetFile, true)  // append            } else {                FileOutputStream(targetFile)            }            responseBody.byteStream().use { input ->                outputStream.use { output ->                    val buffer = ByteArray(8192)                    var bytesRead: Int                    var totalDownloaded = existingSize                    while (input.read(buffer).also { bytesRead = it } != -1) {                        output.write(buffer, 0, bytesRead)                        digest.update(buffer, 0, bytesRead)                        totalDownloaded += bytesRead                        if (expectedSize > 0) {                            onProgress((totalDownloaded.toFloat() / expectedSize).coerceIn(0f, 1f))                        }                    }                }            }            // Verify SHA256 (if provided)            if (expectedSha256 != null) {                val actualHash = digest.digest().toHexString()                if (!actualHash.equals(expectedSha256, ignoreCase = true)) {                    Timber.e("SHA256 mismatch: expected=$expectedSha256 actual=$actualHash")                    targetFile.delete()                    return null                }                Timber.i("SHA256 verified: $fileName")            }            Timber.i("Download complete: $fileName (${targetFile.length()} bytes)")            targetFile.absolutePath        } catch (e: Exception) {            Timber.e(e, "Download failed: $url")            null        }    }    /**     * Delete a model file.     */    fun deleteModel(filePath: String): Boolean {        return try {            File(filePath).delete()        } catch (e: Exception) {            false        }    }    /**     * Get available storage space in MB.     */    fun getAvailableStorageMb(): Long {        return try {            val dir = File(modelsDir)            val stat = android.os.StatFs(dir.absolutePath)            stat.availableBytes / (1024 * 1024)        } catch (e: Exception) {            0L        }    }    /**     * Check if there's enough storage for a model of given size.     */    fun hasEnoughStorage(requiredBytes: Long): Boolean {        val available = getAvailableStorageMb() * 1024 * 1024        return available > requiredBytes * 1.1  // 10% buffer    }    private fun ByteArray.toHexString(): String {        return joinToString("") { "%02x".format(it) }    }}
